class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def sortAbsoluteOrdered(nums):
    head = build(nums)
    if head is None:
        return []
    prev = head
    cur = head.next
    while cur:
        if cur.val < 0:
            prev.next = cur.next
            cur.next = head
            head = cur
            cur = prev.next
        else:
            prev = cur
            cur = cur.next
    return dump(head)
